def pluck(arr):
    if not arr:
        return []

    min_even_value = None
    min_even_index = -1

    for i, value in enumerate(arr):
        if value % 2 == 0:  # Check if the value is even
            if min_even_value is None or value < min_even_value:
                min_even_value = value
                min_even_index = i

    if min_even_value is None:
        return []

    return [min_even_value, min_even_index]
