def anti_shuffle(s):
    words = s.split(' ')
    result = []
    for word in words:
        if word:  # non-empty word
            sorted_word = ''.join(sorted(word))
            result.append(sorted_word)
        else:
            result.append(word)  # keep empty strings (consecutive spaces)
