        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:  # char == ')'
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Try both possible concatenations
    concat1 = lst[0] + lst[1]
    concat2 = lst[1] + lst[0]

    if is_balanced(concat1) or is_balanced(concat2):
        return 'Yes'
    else:
        return 'No'
