def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        count = 0
        for char in txt:
            if char.islower():
                ord_val = ord(char) - ord('a')
                if ord_val % 2 == 1:  # odd order (b, d, f, h, j, l, n, p, r, t, v, x, z)
                    count += 1
        return count
